export function appointmentId(s,cryptoApi=globalThis.crypto){if(typeof cryptoApi?.randomUUID==='function'){const id=cryptoApi.randomUUID();if(!s.appointments.some(a=>a.id===id))return id;}let n=s.appointments.length;let id;do{id=`local-${Date.now().toString(36)}-${(n++).toString(36)}`;}while(s.appointments.some(a=>a.id===id));return id;}
export const labels={pending:'Pendiente',confirmed:'Confirmada',change_requested:'Solicitó cambio',cancelled:'Cancelada'};
export function createState(now=new Date().toISOString()){return {now,appointments:[],messages:[],tasks:[]};}
export function addAppointment(s,{id,patient,start,consent}){if(!id||s.appointments.some(a=>a.id===id))throw Error('La cita ya existe.');if(!patient?.trim()||!Number.isFinite(Date.parse(start))||Date.parse(start)<=Date.parse(s.now))throw Error('Escribe un nombre y una fecha futura.');s.appointments.push({id,patient:patient.trim(),start:new Date(start).toISOString(),consent:!!consent,revision:1,status:'pending'});return id;}
export function appointments(s,{query='',status='all'}={}){return s.appointments.filter(a=>(status==='all'||a.status===status)&&a.patient.toLocaleLowerCase().includes(query.toLocaleLowerCase())).sort((a,b)=>Date.parse(a.start)-Date.parse(b.start));}
export function run(s,fail=false){let count=0;for(const a of s.appointments){const h=(Date.parse(a.start)-Date.parse(s.now))/36e5;if(!a.consent||a.status!=='pending'||h<=0||h>48)continue;const window=h>24?48:24;const key=`${a.id}/${a.revision}/${window}`;if(s.messages.some(m=>m.id===key))continue;s.messages.push({id:key,appointmentId:a.id,revision:a.revision,window,text:`Hola, ${a.patient}. Te recordamos tu cita con la Dra. Laura el ${new Intl.DateTimeFormat('es-MX',{timeZone:'America/Monterrey',dateStyle:'medium',timeStyle:'short'}).format(new Date(a.start))}. ¿Podrás asistir? Puedes confirmar, solicitar cambio o cancelar.`,status:fail?'failed':'delivered'});count++;}return count;}
export function respond(s,id,action){const m=s.messages.find(m=>m.id===id);const a=s.appointments.find(a=>a.id===m?.appointmentId);if(!m||!a||m.status!=='delivered'||m.revision!==a.revision||!['confirmed','change_requested','cancelled'].includes(action))throw Error('Esta respuesta ya no corresponde a una cita vigente.');if(a.status===action)return;if(a.status!=='pending')throw Error('La cita ya tiene otra respuesta.');a.status=action;if(action==='change_requested')s.tasks.push({appointmentId:a.id,revision:a.revision,text:`Contactar a ${a.patient} para acordar otro horario.`});}
export function reschedule(s,id,start){const a=s.appointments.find(a=>a.id===id);if(!a||!Number.isFinite(Date.parse(start))||Date.parse(start)<=Date.parse(s.now))throw Error('Elige una fecha futura.');for(const m of s.messages.filter(m=>m.appointmentId===id))m.status='obsolete';s.tasks=s.tasks.filter(t=>t.appointmentId!==id);a.start=new Date(start).toISOString();a.revision++;a.status='pending';}
export function retry(s,id){const m=s.messages.find(m=>m.id===id);const a=s.appointments.find(a=>a.id===m?.appointmentId);if(!m||m.status!=='failed'||!a||a.revision!==m.revision||a.status!=='pending'||!a.consent||Date.parse(a.start)<=Date.parse(s.now))throw Error('Este envío ya no puede reintentarse.');const h=(Date.parse(a.start)-Date.parse(s.now))/36e5;if((m.window===48&&!(h>24&&h<=48))||(m.window===24&&!(h>0&&h<=24)))throw Error('Este aviso quedó fuera de su ventana. Ejecuta los recordatorios actuales.');m.status='delivered';}
export function metrics(s){return {total:s.appointments.length,pending:s.appointments.filter(a=>a.status==='pending').length,confirmed:s.appointments.filter(a=>a.status==='confirmed').length,failed:s.messages.filter(m=>m.status==='failed').length};}
export function seed(now=new Date().toISOString()){const s=createState(now);for(const [i,name,h,consent] of [[1,'Ana Martínez',30,true],[2,'Luis Ramírez',20,true],[3,'Marta López',44,true],[4,'Pedro García',52,false]])addAppointment(s,{id:`demo-${i}`,patient:name,start:new Date(Date.parse(now)+h*36e5).toISOString(),consent});run(s);respond(s,'demo-3/1/48','confirmed');return migrateState(s);}

const samePatient=(a,b)=>a.trim().toLocaleLowerCase()===b.trim().toLocaleLowerCase();
export function treatmentStatus(t){return t.completed===t.total?'finalizado':t.completed===0?'pendiente':'en proceso';}
export function remainingSessions(t){return t.total-t.completed;}
export function nextSession(s,t){if(!remainingSessions(t))return null;return s.appointments.find(a=>a.id===t.nextAppointmentId&&samePatient(a.patient,t.patient)&&a.status!=='cancelled'&&Date.parse(a.start)>Date.parse(s.now))??null;}
function validateTreatment(s,data,currentId){if(!data.id||(s.treatments??[]).some(t=>t.id===data.id&&t.id!==currentId))throw Error('El identificador del tratamiento ya existe.');if(typeof data.patient!=='string'||!data.patient.trim()||typeof data.label!=='string'||!data.label.trim())throw Error('Escribe un paciente ficticio y una etiqueta administrativa.');if(data.label.trim().length>70)throw Error('La etiqueta debe tener máximo 70 caracteres.');if(!Number.isInteger(data.total)||data.total<2||!Number.isInteger(data.completed)||data.completed<0||data.completed>data.total)throw Error('Usa enteros: total de al menos 2 y realizadas entre 0 y el total.');const result={id:data.id,patient:data.patient.trim(),label:data.label.trim(),total:data.total,completed:data.completed,nextAppointmentId:data.completed===data.total?null:data.nextAppointmentId||null};if(result.nextAppointmentId){const a=nextSession(s,result);if(!a)throw Error('Selecciona una cita futura vigente del mismo paciente.');if((s.treatments??[]).some(t=>t.id!==currentId&&remainingSessions(t)>0&&t.nextAppointmentId===a.id))throw Error('Esta cita ya es la próxima sesión de otro tratamiento activo.');}return result;}
export function addTreatment(s,data){const t=validateTreatment(s,data);(s.treatments??=[]).push(t);return t.id;}
export function updateTreatment(s,id,changes){const index=(s.treatments??[]).findIndex(t=>t.id===id);if(index<0)throw Error('No se encontró el tratamiento.');const result=validateTreatment(s,{...s.treatments[index],...changes,id},id);s.treatments[index]=result;return id;}
export function linkNextSession(s,id,appointmentId){return updateTreatment(s,id,{nextAppointmentId:appointmentId});}
export function scheduleNextSession(s,id,data){const t=s.treatments.find(t=>t.id===id);if(!t||!remainingSessions(t))throw Error('Solo un tratamiento pendiente puede programar próxima sesión.');if(data.patient&&!samePatient(data.patient,t.patient))throw Error('La cita debe ser del mismo paciente.');const aid=addAppointment(s,{...data,patient:t.patient});t.nextAppointmentId=aid;return aid;}
function sampleTreatments(){return [{id:'t-demo-1',patient:'Ana Martínez',label:'Endodoncia · ejemplo',total:4,completed:1,nextAppointmentId:'demo-1'},{id:'t-demo-2',patient:'Luis Ramírez',label:'Ortodoncia · ejemplo',total:3,completed:0,nextAppointmentId:'demo-2'},{id:'t-demo-3',patient:'Marta López',label:'Rehabilitación · ejemplo',total:5,completed:2,nextAppointmentId:null}];}
export function migrateState(s){if(!Object.hasOwn(s,'treatments')){const known=[[1,'Ana Martínez'],[2,'Luis Ramírez'],[3,'Marta López'],[4,'Pedro García']].every(([i,name])=>s.appointments.some(a=>a.id===`demo-${i}`&&a.patient===name));s.treatments=known?sampleTreatments():[];}return s;}
export function treatmentMetrics(s){const treatments=s.treatments??[];return {active:treatments.filter(t=>remainingSessions(t)>0).length,remaining:treatments.reduce((n,t)=>n+remainingSessions(t),0),withoutNext:treatments.filter(t=>remainingSessions(t)>0&&!nextSession(s,t)).length,finished:treatments.filter(t=>remainingSessions(t)===0).length};}
export function treatmentId(s){let n=s.treatments.length;let id;do{id=`t-local-${Date.now().toString(36)}-${(n++).toString(36)}`;}while(s.treatments.some(t=>t.id===id));return id;}
